//! Oura readiness scores, documented in
//! `docs/algorithms/metrics.md`. The vectors in the tests are generated by
//! `tools/gen_public_vectors_readiness.py`.
//!
//! Two independent calculations are implemented:
//!
//! * [`readiness_v2`] (the Readiness 2 screens): seven 0..100
//!   scores from the sleep and recovery pipeline, the night's 30-second hypnograms, 90-day
//!   histories of sleep fragmentation and breathing rate, and the age, combined by weighted
//!   power means (exponent 0.6).
//! * [`readiness_calculate`] (the daily readiness score), which
//!   builds a [`State`] and runs [`recovery_run`]: nine contributors against personal
//!   baselines ([`super::baseline::update_lt_mean_and_dev`]), a weighted mean, and caps from
//!   temperature and rest mode ([`super::rest_recovery`]). [`sri_calculate`] gives the
//!   sleep-regularity contributor from a day-by-slot sleep matrix that the caller keeps.
//!
//! Arithmetic mixes float32 and float64. Rust `f32` operations round to single precision,
//! and `f32::mul_add` is the fused multiply-add. The libm calls (`powf`, `expf`, `log2f`)
//! are evaluated in `f64` and rounded to `f32`, which is the correctly rounded result in all
//! but pathological cases; another libm can differ by one ulp, which only matters on a
//! rounding boundary of the final integer score.

use super::baseline::{self, decode16};
use super::rest_recovery;

const NAN: f32 = f32::NAN;
/// Missing score marker in the v2 inputs.
pub const MISSING: u32 = 0xFFFF_FFFF;

fn powf(a: f32, b: f32) -> f32 {
    (a as f64).powf(b as f64) as f32
}

fn expf(a: f32) -> f32 {
    (a as f64).exp() as f32
}

fn log2f(a: f32) -> f32 {
    (a as f64).log2() as f32
}

/// Round to nearest, ties away from zero, NaN gives 0, infinities saturate. Finite
/// values keep their low 32 bits, so a value beyond the i32 range wraps instead of saturating;
/// the baseline update reads only the low 16 bits of such a value.
fn round_half_away_i32(x: f32) -> i32 {
    if x.is_infinite() {
        return if x > 0.0 { i32::MAX } else { i32::MIN };
    }
    x.round() as i64 as i32
}

/// Python `min(a, b)`: returns `a` unless `b < a`.
fn pymin(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

fn fin(x: f32) -> bool {
    x.is_finite()
}

const C06: f32 = f32::from_bits(0x3F19_999A); // 0.6 as float32
const C1_06: f32 = f32::from_bits(0x3FD5_5555); // 1/0.6 as float32

const W_SLEEP: [f32; 5] = [0.3, 0.2, 0.2, 0.15, 0.15];
const W_NERVOUS: [f32; 3] = [0.35, 0.35, 0.3];
const W_STRAIN: [f32; 3] = [0.4, 0.4, 0.2];
const W_TOP: [f32; 3] = [0.4, 0.3, 0.3];

/// Values equal to `MISSING` (-1 as `u32`) are skipped, 0
/// counts as 1, values of 100 and above as 100. Returns -1 when nothing is left.
pub fn weighted_power_mean(vals: &[u32], weights: &[f32]) -> i32 {
    let (mut sw, mut acc) = (0.0f32, 0.0f32);
    for (&v, &w) in vals.iter().zip(weights) {
        if v == MISSING {
            continue;
        }
        let base = if v == 0 {
            1.0
        } else if v <= 99 {
            v as f32
        } else {
            100.0
        };
        sw += w;
        acc = w.mul_add(powf(base, C06), acc);
    }
    if !(sw > 0.0) {
        return -1;
    }
    let mut x = powf(acc / sw, C1_06);
    if x < 0.0 {
        x = 0.0;
    }
    round_half_away_i32(pymin(x, 100.0))
}

// ---------------------------------------------------------------------------- sub-scores

/// Wake after sleep onset (minutes) to 1..100: a logistic `100 / (1 + exp(0.055 (waso -
/// allowed)))` where the allowed WASO is 60 min at age 20 and below, rising linearly to
/// 120 min at age 80 and above. -1 when `waso_min` is not finite.
pub fn waso_score(waso_min: f32, age: u32) -> i32 {
    if !fin(waso_min) {
        return -1;
    }
    let a = age.clamp(20, 80);
    let t = (a - 20) as f32 / 60.0;
    let thr = if t == 1.0 {
        120.0
    } else {
        pymin(t.mul_add(60.0, 60.0), 120.0)
    };
    let z = (waso_min - thr) * 0.055f32;
    let mut s = 100.0 / (expf(z) + 1.0);
    if s < 1.0 {
        s = 1.0;
    }
    round_half_away_i32(pymin(s, 100.0))
}

/// Sleep fragmentation index against the user's 90-day 25th/75th percentiles: 90 at `p25`, 60
/// at `p75` (slope `-30 / (p75 - p25)`), clamped to 1..100. -1 when `p75 <= p25`.
pub fn sfi_score(sfi: f32, p25: f32, p75: f32) -> i32 {
    if !(p75 > p25) {
        return -1;
    }
    let d = p75 - p25;
    let slope = -30.0 / d;
    let mut s = slope.mul_add(sfi - p25, 90.0);
    if s < 1.0 {
        s = 1.0;
    }
    round_half_away_i32(pymin(s, 100.0))
}

/// Breathing rate score from `z = (x - mean) / max(std, min_std)`: 100 for `z` in [-1, -0.5],
/// `100 (1 - (z + 0.5)/3.5)` above that (0 at `z = 3`), `50 + 50 (z + 4)/3` below -1 (50 at
/// `z = -4`), clamped to 1..100.
pub fn br_score(x: f32, mean: f32, std: f32, min_std: f32) -> i32 {
    let std = if std < min_std { min_std } else { std };
    if !(fin(std) && std > 0.0) {
        return -1;
    }
    let z = (x - mean) / std;
    let mut s;
    if z <= -1.0 {
        let mut t = (z + 4.0) / 3.0;
        if t < 0.0 {
            t = 0.0;
        }
        t = pymin(t, 1.0);
        s = if t == 1.0 {
            100.0
        } else {
            pymin(t.mul_add(50.0, 50.0), 100.0)
        };
    } else if z <= -0.5 {
        s = 100.0;
    } else {
        let mut t = (z + 0.5) / 3.5;
        if t < 0.0 {
            t = 0.0;
        }
        t = pymin(t, 1.0);
        s = t.mul_add(0.0, (1.0 - t) * 100.0);
    }
    if s < 1.0 {
        s = 1.0;
    }
    round_half_away_i32(pymin(s, 100.0))
}

/// Breathing disturbance index to 1..100: full score up to an allowed BDI of `1 + 0.15 (min(age,
/// 80) - 20)` (age floor 20), then 100 minus 4 per index point above it; capped at 30 when the
/// index exceeds 30. -1 when `bdi` is not finite.
pub fn bdi_score(bdi: f32, age: u32) -> i32 {
    if !fin(bdi) {
        return -1;
    }
    let a = (age as f64).max(20.0);
    let y: f32 = if a < 80.0 { (a - 20.0) as f32 } else { 60.0 };
    let thr = y.mul_add(0.15f32, 1.0);
    let d = bdi - thr;
    let lin = d.mul_add(-4.0, 100.0);
    let floored = if lin < 1.0 { 1.0 } else { lin };
    let gated = if d > 0.0 { floored } else { 100.0 };
    let capped = if bdi > 30.0 { pymin(gated, 30.0) } else { gated };
    round_half_away_i32(capped)
}

/// Mean of the deep and REM scores (each clamped to 1..100), rounded down; the available one
/// when the other is `MISSING`. -1 when both are missing.
pub fn restorative_sleep_score(deep: u32, rem: u32) -> i32 {
    let deep_c = (deep as f64).clamp(1.0, 100.0) as f32;
    let rem_c = (rem as f64).clamp(1.0, 100.0) as f32;
    if deep != MISSING && rem != MISSING {
        return ((deep_c + rem_c) * 0.5).floor() as i32;
    }
    if deep == MISSING {
        if rem != MISSING {
            rem_c as i32
        } else {
            -1
        }
    } else {
        deep_c as i32
    }
}

// ---------------------------------------------------------------------------- hypnograms

/// Stage codes in the 30-second hypnogram: 1 deep, 2 light, 3 REM, 4 wake (0 unknown).
fn asleep(s: u8) -> bool {
    (1..=3).contains(&s)
}

fn hypnogram_tst_sec(ph: &[u8]) -> i64 {
    30 * ph.iter().filter(|&&s| asleep(s)).count() as i64
}

/// Seconds awake (stage 4) from the first sleep epoch to the end of the record; -1 when the
/// record has no sleep epoch.
fn hypnogram_waso_sec(ph: &[u8]) -> i64 {
    match ph.iter().position(|&s| asleep(s)) {
        Some(i) if i != 0xFFFF => 30 * ph[i..].iter().filter(|&&t| t == 4).count() as i64,
        _ => -1,
    }
}

/// Number of fragmenting transitions: sleep to wake, deep to light, REM to light. `None` when
/// the record has no sleep epoch.
fn hypnogram_transitions(ph: &[u8]) -> Option<i64> {
    if !ph.iter().any(|&s| asleep(s)) {
        return None;
    }
    Some(
        ph.windows(2)
            .filter(|w| {
                (asleep(w[0]) && w[1] == 4) || (w[0] == 1 && w[1] == 2) || (w[0] == 3 && w[1] == 2)
            })
            .count() as i64,
    )
}

/// the readiness v2 session record: type (0 long sleep, 1 sleep, 2 late nap), hypnogram,
/// breathing rate and breathing disturbance index.
#[derive(Clone, Debug)]
pub struct Session {
    pub kind: u32,
    pub phases: Vec<u8>,
    pub breathing_rate: f32,
    pub bdi: f32,
}

impl Default for Session {
    fn default() -> Self {
        Session {
            kind: 0,
            phases: Vec::new(),
            breathing_rate: NAN,
            bdi: NAN,
        }
    }
}

/// the readiness v2 input record. The seven scores use [`MISSING`] for "not available".
#[derive(Clone, Debug)]
pub struct ReadinessV2Input {
    pub total_sleep: u32,
    pub deep_sleep: u32,
    pub rem_sleep: u32,
    pub hrv_balance: u32,
    pub resting_hr: u32,
    pub recovery_index: u32,
    pub body_temp: u32,
    pub sessions: Vec<Session>,
    pub sfi_history: Option<Vec<f32>>,
    pub br_history: Option<Vec<f32>>,
    pub age: u32,
}

impl Default for ReadinessV2Input {
    fn default() -> Self {
        ReadinessV2Input {
            total_sleep: MISSING,
            deep_sleep: MISSING,
            rem_sleep: MISSING,
            hrv_balance: MISSING,
            resting_hr: MISSING,
            recovery_index: MISSING,
            body_temp: MISSING,
            sessions: Vec::new(),
            sfi_history: None,
            br_history: None,
            age: 0,
        }
    }
}

/// Output of [`readiness_v2`]. Missing scores are stored as 0.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ReadinessV2Output {
    pub score: i32,
    pub sleep_recovery: i32,
    pub nervous_system: i32,
    pub body_strain: i32,
    pub waso_score: i32,
    pub sfi_score: i32,
    pub br_score: i32,
    pub bdi_score: i32,
    pub restorative_sleep: i32,
    pub sfi: f32,
    pub waso_min: f32,
    pub br_avg: f32,
    pub bdi: f32,
    pub sfi_p25: f32,
    pub sfi_p75: f32,
    pub br_mean: f32,
    pub br_std: f32,
}

/// Night summary over the sessions `(SFI per hour of sleep, WASO
/// minutes, mean breathing rate, TST-weighted BDI)`; NaN where undefined. WASO averages the
/// type-0 (long sleep) sessions only.
pub fn aggregate_sessions(sessions: &[Session]) -> (f32, f32, f32, f32) {
    let (mut trans_sum, mut tst_sum, mut waso_n, mut br_n) = (0i64, 0i64, 0i64, 0i64);
    let (mut waso_acc, mut br_acc, mut w_acc, mut wsum) = (0.0f64, 0.0f64, 0.0f64, 0.0f64);
    for s in sessions.iter().take(255) {
        let ph = &s.phases;
        let (mut tst, mut tr, mut waso_ok, mut waso) = (0i64, 0i64, false, 0i64);
        if !ph.is_empty() {
            tst = hypnogram_tst_sec(ph);
            waso = hypnogram_waso_sec(ph);
            waso_ok = waso != -1;
            match hypnogram_transitions(ph) {
                Some(t) => {
                    tst_sum += tst;
                    tr = if tst == 0 { 0 } else { t };
                }
                None => tst = 0,
            }
        }
        trans_sum += tr;
        if s.kind == 0 && waso_ok {
            waso_n += 1;
            waso_acc += waso as f64;
        }
        if fin(s.breathing_rate) {
            br_n += 1;
            br_acc += s.breathing_rate as f64;
        }
        if fin(s.bdi) && tst != 0 {
            w_acc = (s.bdi as f64).mul_add(tst as f64, w_acc);
            wsum += tst as f64;
        }
    }
    let sfi = if tst_sum == 0 {
        NAN
    } else {
        let hours = (tst_sum as f64 / 3600.0) as f32;
        (trans_sum as f64 / hours as f64) as f32
    };
    let waso_min = if waso_n == 0 {
        NAN
    } else {
        (waso_acc / waso_n as f64 / 60.0) as f32
    };
    let br_avg = if br_n == 0 {
        NAN
    } else {
        (br_acc / br_n as f64) as f32
    };
    let bdi = if wsum > 0.0 {
        (w_acc / wsum) as f32
    } else {
        NAN
    };
    (sfi, waso_min, br_avg, bdi)
}

/// 25th and 75th percentile (linear interpolation, float32) of the finite values among the
/// first 90 entries; `None` with fewer than 14 finite values.
pub fn sfi_percentiles(hist: &[f32]) -> Option<(f32, f32)> {
    let mut v: Vec<f32> = hist.iter().take(90).copied().filter(|x| fin(*x)).collect();
    if v.len() < 14 {
        return None;
    }
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let n = v.len();
    let q = |q: f64| {
        let pos = ((n - 1) as f64 * q) as f32;
        let i = pos.floor() as usize;
        let frac = pos - i as f32;
        let (lo, hi) = (v[i], v[(i + 1).min(n - 1)]);
        (1.0 - frac).mul_add(lo, frac * hi)
    };
    Some((q(0.25), q(0.75)))
}

/// Mean and sample standard deviation (both rounded to float32) of the finite breathing-rate
/// history entries among the first 90; `None` with fewer than 14.
pub fn br_baseline(hist: &[f32]) -> Option<(f32, f32)> {
    let (mut n, mut s, mut ss) = (0usize, 0.0f64, 0.0f64);
    for &x in hist.iter().take(90) {
        if fin(x) {
            n += 1;
            s += x as f64;
            ss = (x as f64).mul_add(x as f64, ss);
        }
    }
    if n < 14 {
        return None;
    }
    let mean = s / n as f64;
    let d2 = -(mean * n as f64);
    let mut var = d2.mul_add(mean, ss) / (n - 1) as f64;
    if var < 0.0 {
        var = 0.0;
    }
    Some((mean as f32, var.sqrt() as f32))
}

pub fn readiness_v2(inp: &ReadinessV2Input) -> ReadinessV2Output {
    let (sfi, waso_min, br_avg, bdi) = aggregate_sessions(&inp.sessions);
    let mut o = ReadinessV2Output {
        score: 0,
        sleep_recovery: 0,
        nervous_system: 0,
        body_strain: 0,
        waso_score: 0,
        sfi_score: 0,
        br_score: 0,
        bdi_score: 0,
        restorative_sleep: 0,
        sfi,
        waso_min,
        br_avg,
        bdi,
        sfi_p25: NAN,
        sfi_p75: NAN,
        br_mean: NAN,
        br_std: NAN,
    };
    let waso_s = if fin(waso_min) {
        waso_score(waso_min, inp.age)
    } else {
        -1
    };

    let mut sfi_s = -1;
    if let Some(h) = inp.sfi_history.as_deref().filter(|h| !h.is_empty()) {
        if let Some((p25, p75)) = sfi_percentiles(h) {
            if fin(p25) && fin(p75) {
                o.sfi_p25 = p25;
                o.sfi_p75 = p75;
                if fin(sfi) {
                    sfi_s = sfi_score(sfi, p25, p75);
                }
            }
        }
    }

    let mut br_s = -1;
    if let Some(h) = inp.br_history.as_deref().filter(|h| !h.is_empty()) {
        if let Some((mean, std)) = br_baseline(h) {
            if fin(mean) {
                o.br_mean = mean;
                if fin(std) {
                    o.br_std = std;
                    if fin(br_avg) {
                        br_s = br_score(br_avg, mean, std, 0.5);
                    }
                }
            }
        }
    }

    let bdi_s = if fin(bdi) {
        bdi_score(bdi, inp.age)
    } else {
        -1
    };
    let sleep = weighted_power_mean(
        &[
            inp.total_sleep,
            inp.deep_sleep,
            inp.rem_sleep,
            waso_s as u32,
            sfi_s as u32,
        ],
        &W_SLEEP,
    );
    let resto = restorative_sleep_score(inp.deep_sleep, inp.rem_sleep);
    let nerv = weighted_power_mean(
        &[inp.hrv_balance, inp.resting_hr, inp.recovery_index],
        &W_NERVOUS,
    );
    let strain = weighted_power_mean(&[inp.body_temp, br_s as u32, bdi_s as u32], &W_STRAIN);
    let total = weighted_power_mean(&[sleep as u32, nerv as u32, strain as u32], &W_TOP);
    // missing scores are stored as 0
    let neg = |v: i32| if v == -1 { 0 } else { v };
    o.score = neg(total);
    o.sleep_recovery = neg(sleep);
    o.nervous_system = neg(nerv);
    o.body_strain = neg(strain);
    o.waso_score = neg(waso_s);
    o.sfi_score = neg(sfi_s);
    o.br_score = neg(br_s);
    o.bdi_score = neg(bdi_s);
    o.restorative_sleep = neg(resto);
    o
}

// ---------------------------------------------------------------------------- readiness
// `readiness_calculate` builds a recovery state from the baseline, the 14-day
// histories and the previous day, then `recovery_run` (the version >= 22 path, the
// default) turns the state into nine contributors and the score. Contributors are bytes in
// 1..100 (0 = not available).
//
//   byte  contributor            output field            driver
//    1    last night             last_night_sleep        sleep score against its baseline
//    2    sleep balance          sleep_balance           14-day weighted sleep time
//    3    last day activity      last_day_activity       previous day distance, vigorous and sedentary time
//    4    activity balance       activity_balance        14-day weighted equivalent walking distance
//    5    resting HR             resting_hr              lowest HR of the night
//    6    temperature            temperature             highest skin temperature
//    7    resting HR time        resting_hr_time         time from the lowest HR to the end of the sleep
//    8    HRV balance            hrv_balance             14-day weighted log2(RMSSD)
//    9    sleep regularity       sleep_regularity        `sri_calculate` (external state)
//    0    readiness score        score                   weighted mean of the above

/// 14-day recency weights (oldest first) for sleep time, equivalent distance and HRV.
const W14: [f32; 14] = [
    0.02, 0.05, 0.08, 0.11, 0.15, 0.18, 0.22, 0.30, 0.38, 0.48, 0.55, 0.63, 0.71, 0.72,
];
const WEIGHTS_A: [f32; 9] = [0.15, 0.25, 0.10, 0.10, 0.15, 0.10, 0.0, 0.15, 0.0];
const WEIGHTS_B: [f32; 9] = [0.12, 0.20, 0.07, 0.07, 0.14, 0.04, 0.22, 0.14, 0.0];
const WEIGHTS_B_REST: [f32; 9] = [0.15, 0.10, 0.025, 0.025, 0.25, 0.10, 0.25, 0.10, 0.0];
const WEIGHTS_A_SRI: [f32; 9] = [0.15, 0.15, 0.10, 0.10, 0.15, 0.10, 0.0, 0.15, 0.10];
const WEIGHTS_B_SRI: [f32; 9] = [0.10, 0.08, 0.025, 0.025, 0.25, 0.10, 0.25, 0.10, 0.07];
/// Order in which the combiner walks the summary bytes against the nine weights.
const COMBINE_ORDER: [usize; 9] = [1, 2, 3, 4, 5, 7, 6, 8, 9];
/// Default baseline written into 0x40..0x64 (means, then deviations).
const INIT_MEANS: [u16; 9] = [720, 0, 480, 2880, 8000, 160, 3840, 29360, 4400];
const INIT_DEVS: [u16; 9] = [80, 360, 160, 480, 8000, 64, 1600, 400, 2000];

/// Switches that change the readiness arithmetic. By default the HRV, rest mode, sleep regularity and
/// athlete-adjusted contributors are on and `freeze_baseline` is off.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Features {
    pub hrv_in_readiness: bool,
    pub rest_mode: bool,
    pub sleep_regularity: bool,
    /// When on, no baseline update is run.
    pub freeze_baseline: bool,
    pub athletes: bool,
}

impl Default for Features {
    fn default() -> Self {
        Features {
            hrv_in_readiness: true,
            rest_mode: true,
            sleep_regularity: true,
            freeze_baseline: false,
            athletes: true,
        }
    }
}

fn sx13(v: i32) -> i32 {
    let v = v & 0x1FFF;
    if v & 0x1000 != 0 {
        v - 0x2000
    } else {
        v
    }
}

fn sb(v: i32) -> i32 {
    (v & 0xFF) as u8 as i8 as i32
}

/// `(q + 50) / 100` rounded half away from zero (`q` already divided by 8): floor division.
fn div100_round(q: i32) -> i32 {
    if q >= 1 {
        (q + 50).div_euclid(100)
    } else {
        -((50 - q).div_euclid(100))
    }
}

/// Round `trunc(tq / 8) / 100` half away from zero; `tq` is the offset product.
fn div100_round_q(tq: i32) -> i32 {
    let q = tq / 8;
    if tq >= 8 {
        (q + 50).div_euclid(100)
    } else {
        -((50 - q).div_euclid(100))
    }
}

/// The recovery state `recovery_run` reads: 14 days of sleep minutes (the last slot is the night being
/// scored), the previous-day and 14-day equivalent distance, sedentary and vigorous minutes, the baseline
/// means and deviations (8x scaled, in the order sleep score, sleep time, resting HR, resting HR time,
/// distance, vigorous, sedentary, temperature, HRV), baseline age, wear percent, the 14-day RMSSD history,
/// the HRV baseline age and the time.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct State {
    pub b: [u8; State::SIZE],
}

impl Default for State {
    fn default() -> Self {
        State {
            b: [0; State::SIZE],
        }
    }
}

impl State {
    pub const SIZE: usize = 0x8C;

    pub fn u8(&self, o: usize) -> u8 {
        self.b[o]
    }
    pub fn u16(&self, o: usize) -> u16 {
        self.b[o] as u16 | (self.b[o + 1] as u16) << 8
    }
    pub fn i16_at(&self, o: usize) -> i32 {
        self.u16(o) as i16 as i32
    }
    pub fn u32(&self, o: usize) -> u32 {
        u32::from_le_bytes(self.b[o..o + 4].try_into().unwrap())
    }
    pub fn set16(&mut self, o: usize, v: i32) {
        self.b[o..o + 2].copy_from_slice(&(v as u16).to_le_bytes());
    }
    pub fn set32(&mut self, o: usize, v: u32) {
        self.b[o..o + 4].copy_from_slice(&v.to_le_bytes());
    }

    /// Move the three 14-day histories one day back and clear today's slot.
    pub fn shift_days(&mut self) {
        for (lo, hi) in [(0x04, 0x1E), (0x22, 0x3C), (0x68, 0x82)] {
            self.b.copy_within(lo + 2..hi + 2, lo);
            self.set16(hi, 0);
        }
    }

    /// Restore the default baseline and clear the histories.
    pub fn init_defaults(&mut self) {
        self.b[0..4].fill(0);
        self.b[0x04..0x20].fill(0);
        self.b[0x20..0x22].fill(0);
        self.b[0x22..0x3E].fill(0);
        self.b[0x3E..0x40].fill(0);
        for (i, &v) in INIT_MEANS.iter().enumerate() {
            self.set16(0x40 + 2 * i, v as i32);
        }
        for (i, &v) in INIT_DEVS.iter().enumerate() {
            self.set16(0x52 + 2 * i, v as i32);
        }
        self.b[0x64..0x66].fill(0);
        self.b[0x68..0x84].fill(0);
        self.b[0x84] = 0;
        self.b[0x88..0x8C].fill(0);
    }
}

/// on baseline `item` (0..8) of
/// `s`; `val` is the unscaled value (the update multiplies by 8).
fn baseline_update(
    s: &mut State,
    item: usize,
    val: i32,
    n: u32,
    feats: &Features,
    mean_min: &[i32; 9],
) {
    let (mo, dof) = (0x40 + 2 * item, 0x52 + 2 * item);
    let (mut m, mut d) = (s.u16(mo), s.u16(dof));
    baseline::update_lt_mean_and_dev(
        &mut m,
        &mut d,
        item,
        val as i16,
        n,
        feats.athletes,
        mean_min,
    );
    s.set16(mo, m as i32);
    s.set16(dof, d as i32);
}

/// Summed contributors: `summary[0] = round(sum(w_i c_i) / sum(w_i))` over the contributors
/// `c_i >= 1`, in float32.
fn combine_contributors(summary: &mut [i32; 10], weights: &[f32; 9]) {
    let (mut acc, mut wsum) = (0.0f32, 0.0f32);
    for (&idx, &w) in COMBINE_ORDER.iter().zip(weights) {
        let v = sb(summary[idx]);
        if v >= 1 {
            acc = (v as f32).mul_add(w, acc);
            wsum = w + wsum;
        }
    }
    let res = if wsum > 0.0 { round_half_away_i32(acc / wsum) } else { 0 };
    summary[0] = res.min(100) & 0xFF;
}

/// Round half away from zero, optional lower clamp, cap at 100, truncate to integer.
fn clip(x: f32, lo: Option<i32>) -> i32 {
    let mut r = x.round();
    if let Some(l) = lo {
        if r < l as f32 {
            r = l as f32;
        }
    }
    pymin(r, 100.0) as i32
}

/// Temperature contributor from the highest temperature `t` (hundredths of a degree):
/// `z = (t/100 - mean) / deviation`; 100 for `z` in [-0.5, 0.15], `105 - 25 z` above and
/// `105 + 10 z` below.
fn temperature_contributor(
    s: &mut State,
    t: u32,
    n: u32,
    upd: bool,
    feats: &Features,
    mean_min: &[i32; 9],
) -> i32 {
    let dev = (s.i16_at(0x60) as f32 / 8.0) / 100.0;
    if dev == 0.0 {
        return 0;
    }
    let tc = (t & 0xFFFF) as f32 / 100.0;
    if tc == 0.0 || !(tc < 43.0) {
        return 0;
    }
    let mean = (s.i16_at(0x4E) as f32 * -0.125) / 100.0;
    let dd = tc + mean;
    let z = dd / dev;
    let sc = if z > 0.15 {
        z.mul_add(-25.0, 105.0)
    } else if z >= -0.5 {
        100.0
    } else {
        z.mul_add(10.0, 105.0)
    };
    if dd.abs() < 2.0 && upd {
        baseline_update(s, 7, t as i32, n, feats, mean_min);
    }
    clip(sc, Some(1))
}

/// The rest-mode block `recovery_run` reads (the rest mode state): state byte (0 off, 2/3 resting, 4 recovering), days total
/// and days remaining.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct RestMode {
    pub state: u32,
    pub total: u32,
    pub remaining: u32,
}

/// the sleep summary record: five durations in 30-second units (awake, three sleep durations that
/// sum to total sleep, and `extra`) and byte fields.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SleepSummary {
    pub awake: i64,
    pub rem: i64,
    pub light: i64,
    pub deep: i64,
    pub extra: i64,
    pub b0a: u8,
    pub sleep_score: u8,
    pub b0c: u8,
    pub b0d: u8,
}

impl SleepSummary {
    fn u16(&self, o: usize) -> i64 {
        [self.awake, self.rem, self.light, self.deep, self.extra][o / 2]
    }
}

/// The body of `recovery_run` for version >= 22. `summary` is filled in; `s` is
/// modified in place. `ss` is the sleep summary, `rm` the rest mode, `h` whole hours slept
/// (used when `ss` is `None`), `t` the highest temperature, `flag` is set when the day rolled
/// over, `n2` is the baseline age used by the temperature update, `upd` allows baseline
/// updates, `lowest` is (HR, seconds from bedtime), `f` is log2(RMSSD) and `sri` is the value
/// of `sri_calculate(true)`.
#[allow(clippy::too_many_arguments)]
fn recovery_core(
    summary: &mut [i32; 10],
    s: &mut State,
    ss: Option<&SleepSummary>,
    rm: &RestMode,
    h: i32,
    t: u32,
    flag: bool,
    n2: u32,
    upd: bool,
    lowest: Option<(u32, u32)>,
    f: f32,
    feats: &Features,
    sri: u32,
    mean_min: &[i32; 9],
) {
    if flag && s.u8(0x64) != 0xFF {
        s.b[0x64] += 1;
    }
    let (mut rest_flag, mut rm_state4) = (false, false);
    let mut upd = upd;
    if feats.rest_mode {
        rest_flag = (rm.state & 0xFE) == 2;
        rm_state4 = rm.state == 4;
        if rest_flag {
            upd = false;
        }
    }
    // a stored baseline outside its valid range is replaced by the defaults
    let mut ok = s.u16(0x40).wrapping_sub(0x328) > 0xFCD0
        && s.u16(0x42).wrapping_sub(0x2D08) > 0xD2F0
        && s.u16(0x44).wrapping_sub(0x378) > 0xFD87
        && s.u16(0x46).wrapping_sub(0x2D08) > 0xD2F0
        && s.u16(0x4A).wrapping_sub(0x2D08) > 0xD2F0
        && s.u16(0x4C).wrapping_sub(0x2D08) > 0xD2F0
        && s.i16_at(0x4E) > 0x63FF;
    if ok {
        let hm = s.i16_at(0x50);
        let hm = sx13((hm + if hm < 0 { 7 } else { 0 }) >> 3);
        let e = 2.0f64.powf((hm as f64 / 100.0) as f32 as f64);
        ok = e as i64 <= 0xFF;
    }
    if ok {
        ok = (0x04..0x20).step_by(2).all(|o| s.u16(o) <= 0x5A0)
            && (0x22..0x3E).step_by(2).all(|o| s.i16_at(o) >= 0)
            && (0x68..0x84).step_by(2).all(|o| s.i16_at(o) >= 0);
    }
    if !ok {
        s.init_defaults();
    }
    let nb = s.u8(0x64) as u32;
    let upd = upd && !feats.freeze_baseline;
    let mm = mean_min;

    // 1: last night's sleep score
    let last_score = match ss {
        Some(x) => x.sleep_score as f32,
        None => (10 * (h & 0xFF)).min(85) as f32,
    };
    let dev8 = s.i16_at(0x52) as f32 / 8.0;
    summary[1] = 0;
    if dev8 != 0.0 {
        let delta = last_score + s.i16_at(0x40) as f32 * -0.125;
        let mut contrib = (delta / dev8).mul_add(12.5, 85.0);
        if contrib < 1.0 {
            contrib = 1.0;
        }
        if upd {
            baseline_update(s, 0, round_half_away_i32(last_score), nb, feats, mm);
        }
        summary[1] = clip(contrib, None);
    }

    // 2: sleep balance, 14-day recency-weighted sleep time
    let (today_min, today) = match ss {
        Some(x) => {
            let today_min = ((x.rem + x.light + x.deep) as f64 / 2.0) as f32;
            (today_min, round_half_away_i32(today_min))
        }
        None => {
            let today = ((h & 0xFF) * 55).min(480);
            (today as f32, today)
        }
    };
    if flag {
        s.b.copy_within(0x06..0x20, 0x04);
    }
    s.set16(0x1E, today);
    let today16 = today as i16 as i32;
    let dev8 = s.i16_at(0x54) as f32 / 8.0;
    summary[2] = 0;
    if dev8 != 0.0 {
        let mean8 = s.i16_at(0x42) as f32 / 8.0;
        let (mut acc, mut wsum) = (0.0f32, 0.0f32);
        let vals: Vec<i32> = (0x04..0x1E)
            .step_by(2)
            .map(|o| s.i16_at(o))
            .chain([today16])
            .collect();
        for (&v, &w) in vals.iter().zip(&W14) {
            let w = if v < 1 { 0.0 } else { w };
            wsum += w;
            acc = w.mul_add(v as f32, acc);
        }
        let avg = if wsum != 0.0 { acc / wsum } else { mean8 };
        let z = (avg - mean8) / dev8;
        let cnt = [0x16, 0x18, 0x1A, 0x1C]
            .iter()
            .filter(|&&o| s.i16_at(o) > 0)
            .count()
            + (today16 > 0) as usize;
        let mut raw = z.mul_add(15.0, 85.0);
        if raw < 1.0 {
            raw = 1.0;
        }
        let gated = if cnt < 3 { 0.0 } else { raw };
        if upd && ss.is_some() {
            baseline_update(s, 1, round_half_away_i32(today_min), nb, feats, mm);
        }
        summary[2] = clip(gated, None);
    }

    // 3: previous-day activity against the distance, vigorous and sedentary baselines
    summary[3] = 0;
    if s.u16(0x20) != 0 {
        let wear = s.u8(0x66) as f32 / 100.0;
        if !(wear < 0.33) {
            let d_eq = decode16(s.u16(0x5A)) as f32 / 8.0;
            let d_vig = s.i16_at(0x5C) as f32 / 8.0;
            let d_sed = s.i16_at(0x5E) as f32 / 8.0;
            if d_eq != 0.0 && d_vig != 0.0 && d_sed != 0.0 {
                let eq_m8 = decode16(s.u16(0x48)) as f32 / 8.0;
                let sed_m8 = s.i16_at(0x4C) as f32 / 8.0;
                let vig_m8 = s.i16_at(0x4A) as f32 / 8.0;
                let one_w = 1.0 - wear;
                let (a0, a1, a2) = if feats.athletes {
                    (
                        eq_m8.mul_add(one_w, s.u16(0x20) as f32),
                        s.u8(0x65) as f32,
                        sed_m8.mul_add(one_w, s.u16(0x3E) as f32),
                    )
                } else {
                    (
                        (s.u16(0x20) as f32).mul_add(wear, one_w * eq_m8),
                        (s.u8(0x65) as f32).mul_add(wear, one_w * vig_m8),
                        (s.u16(0x3E) as f32).mul_add(wear, one_w * sed_m8),
                    )
                };
                let r0 = (a0 - eq_m8) / d_eq;
                let r1 = (a1 - vig_m8) / d_vig;
                let r2 = (a2 - sed_m8) / d_sed;
                let zsum = (r0 + r1) + r2;
                let mut contrib = zsum.mul_add(-6.0, 85.0);
                if !(contrib > 0.0) {
                    contrib = 1.0;
                }
                if upd {
                    baseline_update(s, 5, s.u8(0x65) as i32, nb, feats, mm);
                    let mut sed_min = s.u16(0x3E) as i32;
                    if feats.athletes && sed_min != 0 {
                        let sm = s.i16_at(0x4C);
                        let tq = (100 - s.u8(0x66) as i32) * sm + if sm > 0 { 4 } else { -4 };
                        sed_min += div100_round_q(tq);
                    }
                    baseline_update(s, 6, sed_min, nb, feats, mm);
                }
                summary[3] = clip(contrib, Some(1));
            }
        }
    }

    // 4: activity balance, 14-day recency-weighted equivalent distance
    let mean_eq = decode16(s.u16(0x48));
    let mean_eq_f = mean_eq as f32 / 1000.0;
    summary[4] = 0;
    if mean_eq_f != 0.0 {
        let mut dist_today = 0i32;
        if s.u16(0x20) != 0 {
            if feats.athletes {
                let tq = (100 - s.u8(0x66) as i32) * mean_eq + if mean_eq > 0 { 4 } else { -4 };
                dist_today = s.u16(0x20) as i32 + div100_round_q(tq);
            } else {
                let dv = s.i16_at(0x5A);
                let tq = (100 - s.u8(0x66) as i32) * dv + if dv > 0 { 4 } else { -4 };
                dist_today = div100_round(s.u8(0x66) as i32 * s.u16(0x20) as i32 + tq / 8);
            }
        }
        if flag {
            s.b.copy_within(0x24..0x3E, 0x22);
        }
        s.set16(0x3C, dist_today);
        let (mut acc, mut wsum) = (0.0f32, 0.0f32);
        for (i, &wi) in W14.iter().enumerate() {
            let v = s.i16_at(0x22 + 2 * i);
            let w = if v < 1 { 0.0 } else { wi };
            let sc = (v as f32 * 8.0) / 1000.0;
            wsum += w;
            acc = w.mul_add(sc, acc);
        }
        let avg = if wsum != 0.0 { acc / wsum } else { mean_eq_f };
        let d = (avg - mean_eq_f) / mean_eq_f;
        let dist_today16 = dist_today as i16 as i32;
        let cnt = [0x34, 0x36, 0x38, 0x3A]
            .iter()
            .filter(|&&o| s.i16_at(o) > 0)
            .count()
            + (dist_today16 > 0) as usize;
        let mut bal = d + 0.25;
        bal = bal.abs().mul_add(-60.0, 100.0);
        if bal < 1.0 {
            bal = 1.0;
        }
        let gated = if cnt < 3 { 0.0 } else { bal };
        if upd {
            baseline_update(s, 4, dist_today, nb, feats, mm);
        }
        summary[4] = clip(gated, None);
    }

    // 5: resting HR; 7: time of the lowest HR relative to the end of the sleep
    summary[5] = 0;
    summary[7] = 0;
    if let Some((hr, hr_time)) = lowest {
        let dev8 = s.i16_at(0x56) as f32 / 8.0;
        if (1..=179).contains(&hr) && dev8 != 0.0 {
            let delta = hr as f32 + s.i16_at(0x44) as f32 * -0.125;
            let z = delta / dev8;
            let raw = if z > -1.0 {
                z.mul_add(-30.0, 87.5)
            } else {
                z.mul_add(16.0, 116.0)
            };
            let contrib = if raw > 0.0 { raw } else { 1.0 };
            if upd {
                baseline_update(s, 2, hr as i32, nb, feats, mm);
            }
            summary[5] = clip(contrib, Some(1));
        }
        let dev8 = s.i16_at(0x58) as f32 / 8.0;
        if let (Some(x), true) = (ss, hr <= 179 && dev8 != 0.0) {
            let t30 = (hr_time / 30) as i64;
            let tot = (x.u16(6) + x.u16(4)) + (x.u16(2) + x.u16(0));
            let sleep_time = (((tot - t30) as u32) as f64 / 2.0) as f32;
            let delta = sleep_time + s.i16_at(0x46) as f32 * -0.125;
            let time_score = (delta / dev8).mul_add(15.0, 85.0);
            if upd {
                baseline_update(s, 3, round_half_away_i32(sleep_time), nb, feats, mm);
            }
            summary[7] = clip(time_score, Some(1));
        }
    }

    // 6: temperature
    summary[6] = temperature_contributor(s, t, n2, upd, feats, mm);
    if s.u8(0x84) != 0xFF {
        s.b[0x84] += 1;
    }

    // 8: HRV balance, 14-day recency-weighted 100*log2(RMSSD)
    summary[8] = 0;
    let dev8 = s.i16_at(0x62) as f32 / 8.0;
    if dev8 != 0.0 {
        let mean8 = s.i16_at(0x50) as f32 / 8.0;
        let log_h = f * 100.0;
        let today_h = round_half_away_i32(log_h);
        if flag {
            s.b.copy_within(0x6A..0x84, 0x68);
        }
        let nh = s.u8(0x84) as u32;
        s.set16(0x82, today_h);
        let (mut acc, mut wsum) = (0.0f32, 0.0f32);
        for (i, &wi) in W14.iter().enumerate() {
            let v = s.i16_at(0x68 + 2 * i);
            let w = if v < 1 { 0.0 } else { wi };
            acc = w.mul_add(v as f32, acc);
            wsum += w;
        }
        let avg = if wsum != 0.0 { acc / wsum } else { mean8 };
        let z = (avg - mean8) / dev8;
        let th16 = today_h as i16 as i32;
        let cnt = [0x7A, 0x7C, 0x7E, 0x80]
            .iter()
            .filter(|&&o| s.i16_at(o) > 0)
            .count()
            + (th16 > 0) as usize;
        let mut raw = if z > 1.0 {
            z.mul_add(-16.0, 117.0)
        } else {
            z.mul_add(16.0, 85.0)
        };
        if !(z > 0.0) {
            raw = z.mul_add(42.5, 85.0);
        }
        let floored = if raw < 1.0 { 1.0 } else { raw };
        let contrib = if feats.hrv_in_readiness && cnt >= 3 && nh >= 8 {
            floored
        } else {
            0.0
        };
        if log_h > 0.0 && upd {
            baseline_update(s, 8, round_half_away_i32(log_h), nh, feats, mm);
        }
        summary[8] = clip(contrib, None);
    }

    // 9: sleep regularity
    summary[9] = 0x80;
    if feats.sleep_regularity {
        summary[9] = if sri & 0x100 != 0 {
            (sri & 0xFF) as i32
        } else {
            0
        };
    }

    // score
    let (mut wa, mut wb) = (&WEIGHTS_A, &WEIGHTS_B);
    if feats.rest_mode {
        wb = &WEIGHTS_B_REST;
    }
    if feats.sleep_regularity {
        wa = &WEIGHTS_A_SRI;
        wb = &WEIGHTS_B_SRI;
    }
    combine_contributors(summary, wa);
    if feats.rest_mode {
        let temp_contrib = summary[6];
        let flag2 = if ((temp_contrib - 1) as u32) >= 0x4A {
            rest_flag
        } else {
            true
        };
        if !(flag2 || rm_state4) {
            return;
        }
        if rest_flag {
            summary[3] = 0;
            summary[4] = 0;
        }
        let old = summary[0];
        combine_contributors(summary, wb);
        let mut new = sb(summary[0]);
        if new >= 0x51 {
            new = round_half_away_i32(((new - 0x50) as f32 / 5.0) + 80.0);
        }
        if new <= 0x13 {
            new = round_half_away_i32(((20.0 - new as f32) * -0.5) + 20.0);
        }
        let oldsb = sb(old);
        summary[0] = (if flag2 { new.min(oldsb) } else { old }) & 0xFF;
        if !rm_state4 {
            return;
        }
        let (mut cur_f, new_f) = (oldsb as f32, new as f32);
        if !(new_f >= cur_f) {
            let num = (rm.total as i64 - rm.remaining as i64 + 1) as f32;
            let p = pymin(num / (rm.total as i64 + 1) as f32, 1.0);
            cur_f = cur_f.mul_add(p, (1.0 - p) * new_f);
        }
        summary[0] = round_half_away_i32(cur_f) & 0xFF;
    } else {
        if sb(summary[6]) > 0x4A {
            return;
        }
        let old = sb(summary[0]);
        combine_contributors(summary, wb);
        if !(old >= sb(summary[0])) {
            summary[0] = old & 0xFF;
        }
    }
}

/// Lower bounds for the baseline means: [`baseline::mean_min_table`] with feature 9
/// (previous-night contributor minimum, 80).
pub fn mean_min_table(j: u32) -> [i32; 9] {
    baseline::mean_min_table(j, 80)
}

/// `recovery_run` (version >= 22 path). `s` is the state to update and `prev` the previous
/// state (`None` for the state itself); `utc` is the time in seconds, `j` the sleep-time
/// baseline in minutes, `j1` the day number stored at offset 0 and `j2` the baseline age used
/// by the temperature update. `mean_min` defaults to [`mean_min_table`]`(j)`. Returns the ten
/// summary bytes (score, then contributors 1..9) and whether the day rolled over.
#[allow(clippy::too_many_arguments)]
pub fn recovery_run(
    s: &mut State,
    prev: Option<&State>,
    ss: Option<&SleepSummary>,
    rm: &RestMode,
    t: u32,
    h: i32,
    f: f32,
    j: u32,
    j1: u32,
    j2: u32,
    upd: bool,
    lowest: Option<(u32, u32)>,
    utc: i64,
    feats: &Features,
    sri: u32,
    mean_min: Option<&[i32; 9]>,
) -> ([i32; 10], bool) {
    let table = mean_min_table(j);
    let mean_min = mean_min.unwrap_or(&table);
    let mut summary = [0i32; 10];
    let mut day_word = s.u32(0x88) as i64;
    let c1 = day_word != 0 && utc <= ((day_word as u32).wrapping_add(43200)) as i64;
    let new_day = !c1 || (utc + 129600 < day_word);
    let mut flag = new_day;
    if !new_day {
        let prev_b = prev.map_or(s.b, |p| p.b);
        let p88 = u32::from_le_bytes(prev_b[0x88..0x8C].try_into().unwrap());
        if p88 != 0 && utc > p88.wrapping_add(3600) as i64 {
            s.b = prev_b;
            day_word = s.u32(0x88) as i64;
            flag = true;
        }
    }
    if day_word != 0 {
        let mut k = 0;
        while utc > (day_word as u32).wrapping_add(129600) as i64 && k < 14 {
            s.shift_days();
            day_word = (day_word as u32).wrapping_add(86400) as i64;
            k += 1;
        }
    }
    s.set32(0, j1);
    s.set32(0x88, utc as u32);
    recovery_core(
        &mut summary,
        s,
        ss,
        rm,
        h,
        t,
        flag,
        j2,
        upd,
        lowest,
        f,
        feats,
        sri,
        mean_min,
    );
    if ss.is_none() {
        // the first nine bytes are cleared when there is no sleep summary
        let regularity = summary[9];
        summary = [0; 10];
        summary[9] = regularity;
    }
    (summary, new_day)
}

// ---------------------------------------------------------------------------- sleep regularity

/// 10-minute slots of a day.
pub const SRI_COLUMNS: usize = 144;

/// `sri_calculate(bool)`: sleep regularity index over the stored days. `rows` holds one array
/// of 144 slot states per stored day, oldest first (0 asleep, 1 awake, 2 missing). Each slot is
/// compared across days with weights 1..n (recent days weigh more; all 1 when `weighted` is
/// false); the mean of the weighted state minus 0.5, squared, summed over the slots and scaled
/// by 100/36 gives the index. Every slot needs at least 5 non-missing days. Returns a u16: bit 8 set when valid, low byte the index (1..100), 0 when invalid.
pub fn sri_calculate(rows: &[[u8; SRI_COLUMNS]], weighted: bool) -> u32 {
    if rows.is_empty() {
        return 0;
    }
    let mut total = 0.0f32;
    for j in 0..SRI_COLUMNS {
        let (mut num, mut den, mut valid) = (0u32, 0u32, 0u32);
        for (i, row) in rows.iter().enumerate() {
            let v = row[j] as u32;
            let w = if weighted { i as u32 + 1 } else { 1 };
            if v != 2 {
                num += w * v;
                den += w;
                valid += 1;
            }
        }
        if valid & 0xFF < 5 {
            return 0;
        }
        let x = ((num & 0xFF) as f32 / (den & 0xFF) as f32) - 0.5;
        total = x.mul_add(x, total);
    }
    let r = round_half_away_i32((total / 36.0) * 100.0);
    let low = r & 0xFF;
    let val = if low == 0 {
        1
    } else if low > 100 {
        100
    } else {
        r
    };
    (val as u32 & 0xFF) | 0x100
}

// ---------------------------------------------------------------------------- temperature deviation

const NA: i64 = -0x8000;

fn tdiv(a: i64, b: i64) -> i64 {
    a / b
}

/// `(deviation, trend)`. `temp` is today's highest
/// temperature (centidegrees), `base` the baseline temperature (centidegrees, 13-bit field),
/// `hot90` the 90 previous highest temperatures (newest first), `dev3` the three previous
/// deviations (newest first). A deviation is `temp` minus the 30th percentile of the last 90
/// highest temperatures; the trend is the weighted mean (2, 4, 4) of the last three. -0x8000
/// marks missing.
pub fn temperature_deviation(temp: u32, base: u32, hot90: &[u32], dev3: &[i32; 3]) -> (i32, i32) {
    let mut low = temp.wrapping_sub(base) as i32 as i64;
    let (h0, h4) = (dev3[1] as i64, dev3[0] as i64);
    let mut new = NA;
    if temp <= 0x1068 && base.wrapping_sub(200) <= temp {
        let mut vals: Vec<u32> = hot90.iter().take(89).copied().collect();
        vals.push(temp);
        vals.sort_unstable();
        let nz = vals.iter().position(|&v| v != 0).unwrap_or(90);
        let k = nz + (30 * (90 - nz)) / 100;
        new = temp as i64 - vals.get(k).copied().unwrap_or(0) as i64;
    } else {
        low = NA;
    }
    let w = (if h0 != NA { 2 } else { 0 })
        + (if h4 != NA { 4 } else { 0 })
        + (if new != NA { 4 } else { 0 });
    if w < 6 {
        return (low as i32, NA as i32);
    }
    let num = (if h0 != NA { 2 * h0 } else { 0 })
        + (if h4 != NA { 4 * h4 } else { 0 })
        + (if new != NA { 4 * new } else { 0 });
    (low as i32, tdiv(num + (w >> 1), w) as i32)
}

// ---------------------------------------------------------------------------- readiness_calculate

/// The readiness input record (the fields [`readiness_calculate`] reads).
///
/// `p40.1` is the sleep-time baseline in minutes. `prev_day` is the previous day's 8 words:
/// `[1]` equivalent distance in meters, `[3]` sedentary minutes, `[4]` vigorous minutes, `[3..6]`
/// summed for the wear estimate and `[7]` non-wear minutes. `baseline` holds the nine means and the nine deviations.
/// `rest_input` is
/// `(start, end, unused, current midnight)` for rest mode. The 14-day histories are newest
/// first.
#[derive(Clone, Debug)]
pub struct ReadinessInput {
    pub utc: i64,
    pub day_number: u32,
    pub sleep_score: u32,
    pub time_in_bed: u32,
    pub total_sleep: u32,
    pub rem: u32,
    pub deep: u32,
    pub latency: u32,
    pub wake_ups: u32,
    pub highest_temp: u32,
    pub lowest_hr: u32,
    pub lowest_hr_time: u32,
    pub rmssd: u32,
    pub p40: Option<(u32, u32)>,
    pub prev_day: Option<[u32; 8]>,
    pub sleep_sec_14: Option<[u32; 14]>,
    pub distance_14: Option<[u32; 14]>,
    pub rmssd_14: Option<[u32; 14]>,
    pub wear_14: Option<[u8; 14]>,
    pub temp_dev_3: Option<[i32; 3]>,
    pub hot_90: Option<Vec<u32>>,
    pub baseline: Option<[u8; 0x38]>,
    pub cycle_day_type: u8,
    pub rest_input: Option<(i64, i64, i64, i64)>,
}

impl Default for ReadinessInput {
    fn default() -> Self {
        ReadinessInput {
            utc: 0,
            day_number: 0,
            sleep_score: 0,
            time_in_bed: 0,
            total_sleep: 0,
            rem: 0,
            deep: 0,
            latency: 0,
            wake_ups: 0,
            highest_temp: 0,
            lowest_hr: 0,
            lowest_hr_time: 0,
            rmssd: 0,
            p40: Some((0, 0)),
            prev_day: None,
            sleep_sec_14: None,
            distance_14: None,
            rmssd_14: None,
            wear_14: None,
            temp_dev_3: None,
            hot_90: None,
            baseline: None,
            cycle_day_type: 0,
            rest_input: None,
        }
    }
}

/// Output fields. `sleep_regularity` is -1 when not available.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ReadinessOutput {
    pub score: i32,
    pub activity_balance: i32,
    pub last_day_activity: i32,
    pub last_night_sleep: i32,
    pub resting_hr: i32,
    pub resting_hr_time: i32,
    pub sleep_balance: i32,
    pub temperature: i32,
    pub hrv_balance: i32,
    pub sleep_regularity: i32,
    pub temperature_deviation: i32,
    pub temperature_trend_deviation: i32,
}

/// `readiness_calculate`: `None` when a required input block (`p40`, `baseline`) is missing.
/// `sri` is the value `sri_calculate(true)` returns from the sleep-regularity state, which
/// the caller keeps.
pub fn readiness_calculate(
    x: &ReadinessInput,
    feats: &Features,
    sri: u32,
    mean_min: Option<&[i32; 9]>,
) -> Option<ReadinessOutput> {
    readiness_run(x, feats, sri, mean_min, false).map(|(out, _)| out)
}

/// `readiness_calculate` with the baseline update of `recovery_run` switched on: returns the
/// output and the baseline block after the day's values moved the means and deviations
/// (the block to pass as `baseline` for the next day).
pub fn readiness_update(
    x: &ReadinessInput,
    feats: &Features,
    sri: u32,
    mean_min: Option<&[i32; 9]>,
) -> Option<(ReadinessOutput, [u8; 0x38])> {
    readiness_run(x, feats, sri, mean_min, true)
}

fn readiness_run(
    x: &ReadinessInput,
    feats: &Features,
    sri: u32,
    mean_min: Option<&[i32; 9]>,
    upd: bool,
) -> Option<(ReadinessOutput, [u8; 0x38])> {
    let base = x.baseline.as_ref()?;
    let p40 = x.p40?;
    let mut s = State::default();
    let age = x.day_number.min(255);
    for k in 0..9 {
        let m = u16::from_le_bytes([base[0x10 + 4 * k], base[0x11 + 4 * k]]);
        let d = u16::from_le_bytes([base[0x12 + 4 * k], base[0x13 + 4 * k]]);
        s.set16(0x40 + 2 * k, m as i32);
        s.set16(0x52 + 2 * k, d as i32);
    }
    s.b[0x64] = age as u8;
    s.b[0x84] = age as u8;
    s.set32(0x88, x.utc as u32);
    if let Some(pd) = &x.prev_day {
        s.set16(0x20, (pd[1] >> 3) as i32);
        s.set16(0x3E, pd[3] as i32);
        s.b[0x65] = pd[4].min(255) as u8;
        if pd[7] != 0x5A0 {
            let tot = (pd[4]
                .wrapping_add(pd[3])
                .wrapping_add(pd[6].wrapping_add(pd[5]))) as f32;
            let den = 0x5A0u32.wrapping_sub(pd[7]) as f32;
            s.b[0x66] = ((((tot * 100.0) / den) + 0.5) as i64 & 0xFF) as u8;
        }
    }
    let mean_eq_dec = decode16(s.u16(0x48));
    for i in 0..14 {
        if let Some(v) = &x.sleep_sec_14 {
            s.set16(0x1E - 2 * i, round_half_away_i32((v[i] as f64 / 60.0) as f32));
        }
        if let Some(dist) = &x.distance_14 {
            s.set16(0x3C - 2 * i, round_half_away_i32((dist[i] as f64 * 0.125) as f32));
            if let Some(wear) = &x.wear_14 {
                let wp = wear[i] as i32;
                let cur = s.i16_at(0x3C - 2 * i);
                if feats.athletes {
                    let tq = (100 - wp) * mean_eq_dec + if mean_eq_dec > 0 { 4 } else { -4 };
                    s.set16(0x3C - 2 * i, cur + div100_round_q(tq));
                } else {
                    let g = s.i16_at(0x5A);
                    let tq = (100 - wp) * g + if g > 0 { 4 } else { -4 };
                    let v = cur * wp + tq / 8;
                    s.set16(0x3C - 2 * i, div100_round(v));
                }
            }
        }
        if let Some(r) = &x.rmssd_14 {
            let v = r[i];
            let lg = if v == 0 { 0.0 } else { log2f(v as f32) };
            s.set16(0x82 - 2 * i, round_half_away_i32(lg * 100.0));
        }
    }
    let mut rm = RestMode::default();
    if let Some((st, en, un, cm)) = x.rest_input {
        let r = rest_recovery::get_state(&rest_recovery::RestInput {
            start: st,
            end: en,
            unused: un,
            cur_midnight: cm,
        });
        rm = RestMode {
            state: r.state,
            total: r.b,
            remaining: r.c,
        };
    }
    let div30 = |v: u32| round_half_away_i32((v as f64 / 30.0) as f32) as i64;
    let ss = SleepSummary {
        awake: if x.time_in_bed > x.total_sleep {
            div30(x.time_in_bed.wrapping_sub(x.total_sleep))
        } else {
            0
        },
        rem: div30(x.rem),
        light: div30(x.total_sleep.wrapping_sub(x.deep.wrapping_add(x.rem))),
        deep: div30(x.deep),
        extra: div30(x.lowest_hr_time),
        b0a: x.lowest_hr as u8,
        sleep_score: x.sleep_score as u8,
        b0c: x.wake_ups as u8,
        b0d: div30(x.latency) as u8,
    };
    let mut t = x.highest_temp & 0xFFFF;
    if x.cycle_day_type == 2 {
        t = t.wrapping_sub(20) & 0xFFFF;
    }
    let h = round_half_away_i32((x.time_in_bed as f64 / 3600.0) as f32);
    let f = if x.rmssd == 0 {
        0.0
    } else {
        log2f(x.rmssd as f32)
    };
    let (summary, _) = recovery_run(
        &mut s,
        None,
        Some(&ss),
        &rm,
        t,
        h,
        f,
        p40.1,
        0,
        age,
        upd,
        Some((x.lowest_hr, x.lowest_hr_time)),
        x.utc,
        feats,
        sri,
        mean_min,
    );
    let mut out = ReadinessOutput {
        score: sb(summary[0]),
        activity_balance: sb(summary[4]),
        last_day_activity: sb(summary[3]),
        last_night_sleep: sb(summary[1]),
        resting_hr: sb(summary[5]),
        resting_hr_time: sb(summary[7]),
        sleep_balance: sb(summary[2]),
        temperature: sb(summary[6]),
        hrv_balance: sb(summary[8]),
        sleep_regularity: if summary[9] == 0x80 {
            -1
        } else {
            sb(summary[9])
        },
        temperature_deviation: NA as i32,
        temperature_trend_deviation: NA as i32,
    };
    if let (Some(d3), Some(hot)) = (&x.temp_dev_3, &x.hot_90) {
        let bm = u16::from_le_bytes([base[0x2C], base[0x2D]]) as i16 as i32;
        let bt = sx13((bm + if bm < 0 { 7 } else { 0 }) >> 3);
        let (dv, tr) = temperature_deviation(x.highest_temp, bt as u32, hot, d3);
        out.temperature_deviation = dv;
        out.temperature_trend_deviation = tr;
    }
    let mut next = *base;
    for k in 0..9 {
        next[0x10 + 4 * k..0x12 + 4 * k].copy_from_slice(&s.u16(0x40 + 2 * k).to_le_bytes());
        next[0x12 + 4 * k..0x14 + 4 * k].copy_from_slice(&s.u16(0x52 + 2 * k).to_le_bytes());
    }
    Some((out, next))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn same_f(a: f32, b: f32) -> bool {
        if a.is_nan() || b.is_nan() {
            return a.is_nan() && b.is_nan();
        }
        if a.is_infinite() || b.is_infinite() {
            return a == b;
        }
        (a - b).abs() <= F32_TOL * 1.0f32.max(a.abs()).max(b.abs())
    }

    /// Relative tolerance on the float outputs of `readiness_v2` (the Python test uses 1e-5).
    const F32_TOL: f32 = 1e-5;

    fn hex<const N: usize>(s: &str) -> [u8; N] {
        let mut out = [0u8; N];
        for (i, o) in out.iter_mut().enumerate() {
            *o = u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap();
        }
        out
    }

    /// Two bits per slot (0 asleep, 1 awake, 2 missing), four slots per byte, as hex.
    fn unpack_row(s: &str) -> [u8; SRI_COLUMNS] {
        let bytes: [u8; SRI_COLUMNS / 4] = hex(s);
        let mut a = [0u8; SRI_COLUMNS];
        for (k, v) in a.iter_mut().enumerate() {
            *v = (bytes[k / 4] >> (2 * (k % 4))) & 3;
        }
        a
    }

    fn rle(runs: &[(u8, u16)]) -> Vec<u8> {
        runs.iter()
            .flat_map(|&(s, n)| std::iter::repeat(s).take(n as usize))
            .collect()
    }

    #[test]
    fn mean_min_table_entry_one() {
        // trunc(8 * (486 - 1.77 j)) for j = 400 minutes
        assert_eq!(
            mean_min_table(400)[1],
            ((486.0f64 - 1.77 * 400.0) * 8.0) as i32
        );
        assert_eq!(mean_min_table(0)[0], 640);
    }

    #[test]
    fn missing_scores() {
        let o = readiness_v2(&ReadinessV2Input::default());
        assert_eq!(o.score, 0);
        assert_eq!(restorative_sleep_score(MISSING, MISSING), -1);
    }

    macro_rules! vector_tests {
        () => {
            #[test]
            fn v2_matches_reference() {
                for (i, c) in V2_VECTORS.iter().enumerate() {
                    let x = ReadinessV2Input {
                        total_sleep: c.scores[0],
                        deep_sleep: c.scores[1],
                        rem_sleep: c.scores[2],
                        hrv_balance: c.scores[3],
                        resting_hr: c.scores[4],
                        recovery_index: c.scores[5],
                        body_temp: c.scores[6],
                        sessions: c
                            .sessions
                            .iter()
                            .map(|&(kind, runs, breathing_rate, bdi)| Session {
                                kind,
                                phases: rle(runs),
                                breathing_rate,
                                bdi,
                            })
                            .collect(),
                        sfi_history: c.sfi_history.map(|h| h.to_vec()),
                        br_history: c.br_history.map(|h| h.to_vec()),
                        age: c.age,
                    };
                    let o = readiness_v2(&x);
                    let got_i = [
                        o.score,
                        o.sleep_recovery,
                        o.nervous_system,
                        o.body_strain,
                        o.waso_score,
                        o.sfi_score,
                        o.br_score,
                        o.bdi_score,
                        o.restorative_sleep,
                    ];
                    assert_eq!(got_i, c.ints, "case {i}");
                    let got_f = [
                        o.sfi, o.waso_min, o.br_avg, o.bdi, o.sfi_p25, o.sfi_p75, o.br_mean, o.br_std,
                    ];
                    for k in 0..8 {
                        assert!(
                            same_f(got_f[k], c.floats[k]),
                            "case {i} float {k}: {} vs {}",
                            got_f[k],
                            c.floats[k]
                        );
                    }
                }
            }

            #[test]
            fn readiness_calculate_matches_reference() {
                for (i, (x, f, rows, want)) in legacy_vectors().into_iter().enumerate() {
                    let feats = Features {
                        hrv_in_readiness: f[0],
                        rest_mode: f[1],
                        sleep_regularity: f[2],
                        freeze_baseline: false,
                        athletes: f[3],
                    };
                    let rows: Vec<[u8; SRI_COLUMNS]> = rows.iter().map(|r| unpack_row(r)).collect();
                    let sri = sri_calculate(&rows, true);
                    let o = readiness_calculate(&x, &feats, sri, None);
                    let got = o.map(|o| {
                        [
                            o.score,
                            o.activity_balance,
                            o.last_day_activity,
                            o.last_night_sleep,
                            o.resting_hr,
                            o.resting_hr_time,
                            o.sleep_balance,
                            o.temperature,
                            o.hrv_balance,
                            o.sleep_regularity,
                            o.temperature_deviation,
                            o.temperature_trend_deviation,
                        ]
                    });
                    assert_eq!(got, want, "case {i}");
                }
            }

            #[test]
            fn recovery_run_matches_reference() {
                for (i, c) in RECOVERY_VECTORS.iter().enumerate() {
                    let mut s = State {
                        b: hex::<0x8C>(c.state),
                    };
                    let prev = State {
                        b: hex::<0x8C>(c.prev),
                    };
                    let ss = c.sleep_summary.map(|v| SleepSummary {
                        awake: v[0],
                        rem: v[1],
                        light: v[2],
                        deep: v[3],
                        extra: v[4],
                        b0a: 0,
                        sleep_score: v[5] as u8,
                        b0c: 0,
                        b0d: 0,
                    });
                    let rm = RestMode {
                        state: c.rest[0],
                        total: c.rest[1],
                        remaining: c.rest[2],
                    };
                    let feats = Features {
                        hrv_in_readiness: c.feats[0],
                        rest_mode: c.feats[1],
                        sleep_regularity: c.feats[2],
                        freeze_baseline: c.feats[3],
                        athletes: c.feats[4],
                    };
                    let (summary, ret) = recovery_run(
                        &mut s,
                        Some(&prev),
                        ss.as_ref(),
                        &rm,
                        c.t,
                        c.h,
                        c.f,
                        c.j,
                        c.j1,
                        c.j2,
                        c.upd,
                        c.lowest,
                        c.utc,
                        &feats,
                        0,
                        None,
                    );
                    assert_eq!(summary.map(|v| v as u8), c.summary, "case {i} summary");
                    assert_eq!(ret, c.ret, "case {i} day flag");
                    let want: [u8; 0x8C] = hex(c.out_state);
                    let diff: Vec<_> = (0..0x8C)
                        .filter(|&k| s.b[k] != want[k])
                        .map(|k| (k, want[k], s.b[k]))
                        .collect();
                    assert!(
                        diff.is_empty(),
                        "case {i} state diff (offset, want, got): {diff:?}"
                    );
                }
            }

            #[test]
            fn baseline_update_matches_reference() {
                let table = {
                    let mut t = baseline::MEAN_MIN_DEFAULT;
                    t[0] = 640;
                    t
                };
                for (i, &(item, m, d, val, n, ath, want_m, want_d)) in BASELINE_VECTORS.iter().enumerate() {
                    let (mut gm, mut gd) = (m, d);
                    baseline::update_lt_mean_and_dev(&mut gm, &mut gd, item, val, n, ath, &table);
                    assert_eq!(
                        (gm, gd),
                        (want_m, want_d),
                        "case {i}: item {item} m {m} d {d} val {val} n {n} ath {ath}"
                    );
                }
            }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/readiness.rs");
        vector_tests!();
    }

}
